describe('sumUsage', () => {
  it('adds each token field of a round to the running total', () => {
    const total = sumUsage({inputTokens: 1, outputTokens: 2, totalTokens: 3}, {inputTokens: 10, outputTokens: 20, totalTokens: 30});
    expect(total).toEqual({inputTokens: 11, outputTokens: 22, totalTokens: 33});
  });

  it('keeps the total when a round reports nothing, and starts from the round when there is no total', () => {
    const usage = {inputTokens: 1, outputTokens: 2, totalTokens: 3};
    expect(sumUsage(usage, undefined)).toEqual(usage);
    expect(sumUsage(undefined, usage)).toEqual(usage);
    expect(sumUsage(undefined, undefined)).toBeUndefined();
  });
});
EOF
